     4	/**
     5	 * Best-effort guess at an API's production base URL, so the setup prompt
     6	 * arrives pre-filled instead of asking the user to go look it up.
     7	 *
     8	 * Everything here is a local read of committed files - deployment manifests,
     9	 * env TEMPLATES (`.env.example` and friends, never a real `.env`), the
    10	 * README. Nothing is sent anywhere; the guess is offered as an editable
    11	 * default the user can accept with one keystroke or type over.
    12	 *
    13	 * Ordered by how deliberate the signal is: a spec's `servers` entry or a
    14	 * deploy manifest is a decision someone made, a README URL is a decent
    15	 * inference, and `package.json`'s `homepage` is often a marketing site, so
    16	 * it goes last.
    17	 */
    18	
    19	// Hosts that appear in READMEs and configs but are never someone's API.
    20	const NEVER_HOSTS = [
    21	  'localhost', '127.0.0.1', '0.0.0.0', '::1',
    22	  'example.com', 'example.org', 'acme.com',
    23	  'github.com', 'raw.githubusercontent.com', 'gitlab.com',
    24	  'npmjs.com', 'www.npmjs.com', 'img.shields.io', 'shields.io',
    25	  'codecov.io', 'travis-ci.org', 'circleci.com', 'badge.fury.io',
    26	  'openapis.org', 'spec.openapis.org', 'json-schema.org', 'swagger.io',
    27	  'opensource.org', 'choosealicense.com', 'nodejs.org', 'npmtrends.com',
    28	];
    29	
    30	/** Is this a URL we'd be willing to show as someone's production API? */
    31	export function isPlausibleBaseUrl(url) {
    32	  if (!url || typeof url !== 'string') return false;
    33	  let u;
    34	  try { u = new URL(url.trim()); } catch { return false; }
    35	  if (!/^https?:$/.test(u.protocol)) return false;
    36	  const host = u.hostname.toLowerCase();
    37	  if (NEVER_HOSTS.includes(host)) return false;
    38	  if (host.endsWith('.local') || host.endsWith('.internal')) return false;
    39	  // A bare hostname with no dot is a container/service name, not public.
    40	  if (!host.includes('.')) return false;
    41	  // Private / loopback / link-local IPv4 ranges are dev addresses.
    42	  if (/^(10\.|127\.|192\.168\.|169\.254\.|172\.(1[6-9]|2\d|3[01])\.)\d/.test(host)) return false;
    43	  return true;
    44	}
    45	
    46	/** Trailing slashes only ever cause double-slash bugs downstream. */
    47	export function normalize(url) {
    48	  if (!url) return null;
    49	  const trimmed = String(url).trim().replace(/[)>,.'"`]+$/, '');
    50	  if (!isPlausibleBaseUrl(trimmed)) return null;
    51	  return trimmed.replace(/\/+$/, '');
    52	}
