    54	/**
    55	 * Gate for a spec that is about to be recorded and eventually uploaded:
    56	 * is `servers[0].url` something we're willing to publish as this API's
    57	 * base URL? Three outcomes:
    58	 *
    59	 *   ok + url       - a plausible public URL (normalized).
    60	 *   ok + relative  - a path-only server ("/", "/v1"): the honest form for
    61	 *                    an API with no public URL. Nothing to publish.
    62	 *   not ok         - localhost, a loopback/container host, a dev port -
    63	 *                    an address that must not ship to the dashboard.
    64	 *
    65	 * A missing/empty servers array is fine (OAS defaults it to "/").
    66	 */
    67	export function checkOasServers(oas) {
    68	  const first = oas?.servers?.[0]?.url;
    69	  if (!first || typeof first !== 'string' || !first.trim()) return { ok: true, url: null };
    70	  const url = first.trim();
    71	  if (url.startsWith('/')) return { ok: true, url, relative: true };
    72	  if (isPlausibleBaseUrl(url)) return { ok: true, url: normalize(url) };
    73	  return { ok: false, url };
    74	}
