    76	/** `servers[0].url` from a spec the user (or their framework) wrote. */
    77	export function fromOas(oas) {
    78	  for (const server of oas?.servers || []) {
    79	    const url = normalize(server?.url);
    80	    if (url) return url;
    81	  }
    82	  return null;
    83	}
