    85	/** fly.toml: `app = "my-api"` publishes at `<app>.fly.dev`. */
    86	export function fromFlyToml(text) {
    87	  const m = String(text).match(/^\s*app\s*=\s*["']([\w-]+)["']/m);
    88	  return m ? normalize(`https://${m[1]}.fly.dev`) : null;
    89	}
