    91	/** render.yaml: the first web service's name maps to `<name>.onrender.com`. */
    92	export function fromRenderYaml(text) {
    93	  const lines = String(text).split('\n');
    94	  let name = null;
    95	  let sawWeb = false;
    96	  for (const line of lines) {
    97	    const nameMatch = line.match(/^\s*-?\s*name:\s*["']?([\w-]+)["']?\s*$/);
    98	    if (nameMatch) name = nameMatch[1];
    99	    if (/^\s*type:\s*web\s*$/.test(line)) { sawWeb = true; break; }
   100	  }
   101	  return sawWeb && name ? normalize(`https://${name}.onrender.com`) : null;
   102	}
