   104	/** vercel.json: an `alias` is the domain the deployment answers on. */
   105	export function fromVercelJson(text) {
   106	  try {
   107	    const cfg = JSON.parse(text);
   108	    const alias = Array.isArray(cfg.alias) ? cfg.alias[0] : cfg.alias;
   109	    if (alias) return normalize(/^https?:\/\//.test(alias) ? alias : `https://${alias}`);
   110	  } catch {}
   111	  return null;
   112	}
   113	
   114	/** serverless.yml with the domain-manager plugin: `domainName: api.x.com`. */
   115	export function fromServerless(text) {
   116	  const m = String(text).match(/domainName:\s*["']?([\w.-]+\.[a-z]{2,})["']?/i);
   117	  return m ? normalize(`https://${m[1]}`) : null;
   118	}
   119	
   120	/** Traefik routing labels in compose files: ``Host(`api.example.com`)``. */
   121	export function fromCompose(text) {
   122	  const m = String(text).match(/Host\(\s*[`"']([\w.-]+\.[a-z]{2,})[`"']\s*\)/i);
   123	  return m ? normalize(`https://${m[1]}`) : null;
   124	}
   125	
   126	/** A Kubernetes Ingress rule: `- host: api.example.com`. */
   127	export function fromIngress(text) {
   128	  if (!/kind:\s*Ingress/i.test(text)) return null;
   129	  const m = String(text).match(/^\s*-?\s*host:\s*["']?([\w.-]+\.[a-z]{2,})["']?/m);
   130	  return m ? normalize(`https://${m[1]}`) : null;
   131	}
   132	
   133	// Env var names that hold an API's own address, most specific first.
   134	const ENV_KEYS = [
   135	  'API_BASE_URL', 'API_URL', 'BASE_URL', 'PUBLIC_API_URL', 'SERVER_URL',
   136	  'APP_URL', 'PUBLIC_URL', 'NEXT_PUBLIC_API_URL', 'VITE_API_URL', 'HOST_URL',
   137	];
   138	
   139	/**
   140	 * An env TEMPLATE (`.env.example`), never a real `.env`. Templates are
   141	 * committed and usually carry the production value as an illustration; real
   142	 * env files hold secrets and are off-limits.
   143	 */
   144	export function fromEnvTemplate(text) {
   145	  const lines = String(text).split('\n');
   146	  for (const key of ENV_KEYS) {
   147	    for (const line of lines) {
   148	      const m = line.match(new RegExp(`^\\s*(?:export\\s+)?${key}\\s*=\\s*["']?([^"'\\s#]+)`));
   149	      const url = m && normalize(m[1]);
   150	      if (url) return url;
   151	    }
   152	  }
   153	  return null;
   154	}
   155	
   156	/** package.json `homepage` - often a docs or marketing site, so it ranks low. */
   157	export function fromPackageJson(text) {
   158	  try {
   159	    return normalize(JSON.parse(text).homepage);
   160	  } catch {
   161	    return null;
   162	  }
   163	}
   164	
   165	/**
   166	 * A README's own examples. Prefer URLs that look like an API (an `api.`
   167	 * host, or a versioned/`/api` path) over a project's marketing link, and
   168	 * prefer ones inside a curl example over prose.
   169	 */
   170	export function fromReadme(text) {
   171	  const urls = String(text).match(/https?:\/\/[^\s"'`)<>\]]+/g) || [];
   172	  const candidates = urls.map(normalize).filter(Boolean);
   173	  const apiish = candidates.filter((u) => {
   174	    try {
   175	      const { hostname, pathname } = new URL(u);
   176	      return /^api[.-]/.test(hostname) || /\/(api|v\d+)(\/|$)/.test(pathname);
   177	    } catch { return false; }
   178	  });
   179	  const pick = apiish[0] || null;
   180	  if (!pick) return null;
   181	  // Keep scheme + host + any mount prefix, drop a specific endpoint path.
   182	  try {
   183	    const u = new URL(pick);
   184	    const prefix = u.pathname.match(/^\/(api|v\d+)(\/(api|v\d+))?/);
   185	    return normalize(`${u.protocol}//${u.host}${prefix ? prefix[0] : ''}`);
   186	  } catch {
   187	    return pick;
   188	  }
   189	}
   190	
   191	// Where to look, in order. Each entry names a file and the parser for it.
   192	const FILE_SOURCES = [
   193	  { file: 'fly.toml', parse: fromFlyToml },
   194	  { file: 'render.yaml', parse: fromRenderYaml },
   195	  { file: 'render.yml', parse: fromRenderYaml },
   196	  { file: 'vercel.json', parse: fromVercelJson },
   197	  { file: 'serverless.yml', parse: fromServerless },
   198	  { file: 'serverless.yaml', parse: fromServerless },
   199	  { file: 'docker-compose.yml', parse: fromCompose },
   200	  { file: 'docker-compose.yaml', parse: fromCompose },
   201	  { file: 'compose.yml', parse: fromCompose },
   202	  { file: 'ingress.yaml', parse: fromIngress },
   203	  { file: 'ingress.yml', parse: fromIngress },
   204	  { file: 'k8s/ingress.yaml', parse: fromIngress },
   205	  { file: '.env.example', parse: fromEnvTemplate },
   206	  { file: '.env.sample', parse: fromEnvTemplate },
   207	  { file: '.env.template', parse: fromEnvTemplate },
   208	  { file: 'README.md', parse: fromReadme },
   209	  { file: 'readme.md', parse: fromReadme },
   210	  { file: 'package.json', parse: fromPackageJson },
   211	];
