   215	function read(file) {
   216	  try {
   217	    if (fs.statSync(file).size > MAX_BYTES) return null;
   218	    return fs.readFileSync(file, 'utf8');
   219	  } catch {
   220	    return null;
   221	  }
   222	}
   223	
   224	/**
   225	 * Guess the base URL for an API. `dirs` are searched in order (the API's own
   226	 * directory first, then the repo root), so a monorepo package's own fly.toml
   227	 * beats the umbrella repo's README.
   228	 *
   229	 * Returns `{ url, source }` - `source` is a short human label for the dim
   230	 * "we got this from X" line - or null when nothing plausible turned up.
   231	 */
   232	export function guessBaseUrl({ dirs = [], oas = null } = {}) {
   233	  const fromSpec = fromOas(oas);
   234	  if (fromSpec) return { url: fromSpec, source: 'the spec' };
   235	
   236	  const seen = new Set();
   237	  for (const dir of dirs) {
   238	    if (!dir || seen.has(dir)) continue;
   239	    seen.add(dir);
   240	    for (const { file, parse } of FILE_SOURCES) {
   241	      const full = path.join(dir, file);
   242	      const text = read(full);
   243	      if (!text) continue;
   244	      const url = parse(text);
   245	      if (url) return { url, source: file };
   246	    }
   247	  }
   248	  return null;
   249	}
