const DIR_GITIGNORE = `# Scratch files npx restless writes here. Everything else in
# this directory is source - see README.md - and belongs in your commits.
.oas-refresh/
.oas-candidates.json
`;

export function saveSettings(cwd, settings) {
  const dir = path.join(cwd, '.restless');
  if (!fs.existsSync(dir)) {
    safeMkdirSync(dir, { recursive: true });
  }
  // Written when absent, never rewritten - if someone edits or deletes either
  // of these, that's their call to keep. Absent rather than on-creation so an
  // install that predates them picks them up on its next save.
  for (const [name, body] of [['README.md', DIR_README], ['.gitignore', DIR_GITIGNORE]]) {
